require __DIR__ . '/vendor/autoload.php';

use WebCommander\Sdk\Client\WebCommanderClient;
use WebCommander\Sdk\Config\AuthConfig;
use WebCommander\Sdk\Config\SdkConfig;

$auth = new AuthConfig(
    baseUrl: (string) getenv('WC_BASE_URL'),
    clientId: (string) getenv('WC_CLIENT_ID'),
    clientSecret: (string) getenv('WC_CLIENT_SECRET'),
    redirectUri: (string) getenv('WC_REDIRECT_URI'),
    authString: (string) getenv('WC_AUTH_STRING'),
    clientName: 'default',
    grantType: 'client_credentials',
);

$client = new WebCommanderClient(new SdkConfig($auth, raiseOnError: true));
